<?php
require_once __DIR__.'/../includes/auth.php'; require_role('admin');
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$pdo->prepare("INSERT INTO laboratories(name,department,building,room_number,description) VALUES(?,?,?,?,?)")->execute([trim($_POST['name']),trim($_POST['department']),trim($_POST['building']),trim($_POST['room_number']),trim($_POST['description'])]);flash('Laboratory added.');redirect('laboratories.php');}
$rows=$pdo->query("SELECT * FROM laboratories ORDER BY name")->fetchAll();page_header('Laboratory Management','admin');?>
<div class="panel mb-4"><h2 class="section-title">Add laboratory</h2><form method="post" class="row g-2"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><?php foreach(['name'=>'Laboratory name','department'=>'Department','building'=>'Building','room_number'=>'Room number','description'=>'Description'] as $k=>$v):?><div class="col-md-4"><input class="form-control" name="<?=$k?>" placeholder="<?=$v?>" required></div><?php endforeach?><div class="col-12"><button class="btn btn-primary">Add laboratory</button></div></form></div><div class="panel"><h2 class="section-title">Laboratories</h2><?php foreach($rows as $r):?><p><b><?=e($r['name'])?></b> · <?=e($r['department'])?> · <?=e($r['building'])?> / <?=e($r['room_number'])?></p><?php endforeach?></div><?php page_footer();?>
